import sqlite3

def debug_issue():
    conn = sqlite3.connect('magaza.db')
    cursor = conn.cursor()

    # Temiz veritabanı kurulumu
    cursor.executescript('''
    DROP TABLE IF EXISTS iadeler;
    DROP TABLE IF EXISTS siparis_kalemleri;
    DROP TABLE IF EXISTS siparisler;
    DROP TABLE IF EXISTS urunler;
    DROP TABLE IF EXISTS musteriler;

    CREATE TABLE musteriler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, sehir TEXT NOT NULL, kayit_tarihi TEXT NOT NULL);
    CREATE TABLE urunler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, kategori TEXT NOT NULL, fiyat REAL NOT NULL);
    CREATE TABLE siparisler (id INTEGER PRIMARY KEY, musteri_id INTEGER NOT NULL REFERENCES musteriler(id), tarih TEXT NOT NULL);
    CREATE TABLE siparis_kalemleri (siparis_id INTEGER NOT NULL REFERENCES siparisler(id), urun_id INTEGER NOT NULL REFERENCES urunler(id), adet INTEGER NOT NULL, birim_fiyat REAL NOT NULL);
    CREATE TABLE iadeler (id INTEGER PRIMARY KEY, siparis_id INTEGER NOT NULL REFERENCES siparisler(id), urun_id INTEGER NOT NULL REFERENCES urunler(id), adet INTEGER NOT NULL);
    ''')

    # Test Verisi
    cursor.execute("INSERT INTO musteriler (ad, sehir, kayit_tarihi) VALUES ('A', 'B', '2024-01-01')")
    cursor.execute("INSERT INTO urunler (ad, kategori, fiyat) VALUES ('E1', 'Elektronik', 100), ('E2', 'Elektronik', 50), ('K1', 'Kitap', 20), ('H1', 'Ev', 10), ('G1', 'Gıda', 5)")

    # 2025 Siparişleri
    cursor.execute("INSERT INTO siparisler (musteri_id, tarih) VALUES (1, '2025-01-01')") # S1
    cursor.execute("INSERT INTO siparisler (musteri_id, tarih) VALUES (1, '2025-06-01')") # S2

    # 2025 Kalemler
    cursor.execute("INSERT INTO siparis_kalemleri VALUES (1, 1, 2, 100)") # Elektronik: 200
    cursor.execute("INSERT INTO siparis_kalemleri VALUES (2, 2, 1, 50)")  # Elektronik: 50 -> Toplam Elektronik: 250
    cursor.execute("INSERT INTO siparis_kalemleri VALUES (1, 3, 5, 20)")  # Kitap: 100
    cursor.execute("INSERT INTO siparis_kalemleri VALUES (2, 5, 1, 5)")    # Gıda: 5

    # 2024 Siparişi (Hariç tutulmalı)
    cursor.execute("INSERT INTO siparisler (musteri_id, tarih) VALUES (1, '2024-12-31')") # S3
    cursor.execute("INSERT INTO siparis_kalemleri VALUES (3, 4, 10, 10)") # Ev (2024): 100 - (2025'te 0 olmalı)

    conn.commit()

    with open('cevap.sql', 'r') as f:
        query = f.read()

    try:
        cursor.execute(query)
        rows = cursor.fetchall()
        print("SQL Sonuçları (Beklenen: Elektronik 250, Kitap 100, Gıda 5, Ev 0):")
        for row in rows:
            print(row)
        return True
    except Exception as e:
        print(f"Hata: {e}")
        return False
    finally:
        conn.close()

if __name__ == "__main__":
    debug_issue()

